bool is_valid_mtrr_msr(unsigned msr) {
    switch (msr) {
        case 0x200 ... 0x2ff: // MTRR Range Registers
        case 0x2f0 ... 0x2ff: // MTRR Fixed Range Registers
        case 0x2a0:          // MTRR DefType
        case 0x2e0:          // MTRR Capabilities
            return true;
        default:
            return false;
    }
}

bool is_valid_mtrr_msr(unsigned msr) {
    switch (msr) {
        case 0x200 ... 0x2ff: // Valid MTRR range
            return true;
        case 0x2af: // Valid MTRR constant
            return true;
        case 0x2bf: // Valid MTRR constant
            return true;
        default:
            return false;
    }
}

bool is_valid_mtrr_msr(unsigned msr) {
    switch (msr) {
        case 0x200 ... 0x2FF: // MTRR range (0x200 to 0x2FF)
        case 0x2AF:          // MTRR DefType
            return true;
        default:
            return false;
    }
}

